What is the Swift code to create a table for displaying JSON data retrieved from an API call in an iOS app? Assuming the JSON data has already been fetched and stored in a variable named "jsonData", the following Swift code can be used to create a table:
```
struct Result: Codable {
    let column1: String
    let column2: String
    let column3: String
}
guard let data = jsonData.data(using: .utf8) else {
    return
}
do {
    let resultArray = try JSONDecoder().decode([Result].self, from: data)
    let tableView = UITableView()
    tableView.dataSource = self
    tableView.register(UITableViewCell.self, forCellReuseIdentifier: "cell")
    view.addSubview(tableView)

    // Implement UITableViewDataSource methods to display data in the table view
    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return resultArray.count
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "cell", for: indexPath)
        let result = resultArray[indexPath.row]
        cell.textLabel?.text = "\(result.column1) | \(result.column2) | \(result.column3)"
        return cell
    }

} catch {
    print("Error decoding JSON: \(error)")
}
```
This will create a table view with three columns and as many rows as there are objects in the JSON data. The first column will display the value of "column1" in each object, the second column will display the value of "column2", and the third column will display the value of "column3".

