```swift
func correctSentence(sentence: String) -> String {
    let words = sentence.components(separatedBy: " ")
    if words.count < 3 {
        return "Error: Sentence must contain subject, verb, and object."
    }
    if words[0].lowercased() == "i" {
        words[0] = "I"
    } else {
        words[0] = words[0].capitalized
    }
    words[words.count - 1] = words[words.count - 1].replacingOccurrences(of: ".", with: "")
    let correctedSentence = words.joined(separator: " ") + "."
    let regex = try! NSRegularExpression(pattern: "(\\b[A-Z][^\\.?!]*[\\.?!])", options: .caseInsensitive)
    let range = NSRange(location: 0, length: correctedSentence.utf16.count)
    let matches = regex.matches(in: correctedSentence, options: [], range: range)
    if matches.count != 1 {
        return "Error: Sentence structure must follow subject-verb-object format."
    }
    return correctedSentence
}
```
This implementation first checks if the sentence contains at least three words (i.e. subject, verb, and object). If it does not, an error message is returned. Then, it capitalizes the first word and removes any period at the end of the sentence. The `NSRegularExpression` class is used to match the sentence against a regular expression that checks for a single sentence in the subject-verb-object format. If there is more than one match, an error message is returned. Otherwise, the corrected sentence is returned.

