Here is the C# code that can help us achieve this:
XDocument doc = XDocument.Load("economic_data.xml");
var industries = doc.Descendants("industry");
decimal highestMargin = 0;
decimal lowestMargin = decimal.MaxValue;
string highestIndustry = "";
string lowestIndustry = "";
foreach (var industry in industries)
{
    string name = industry.Attribute("name").Value;
    decimal revenue = decimal.Parse(industry.Element("revenue").Value);
    decimal expenses = decimal.Parse(industry.Element("expenses").Value);
    decimal profit = decimal.Parse(industry.Element("profit").Value);
    decimal margin = (profit / revenue) * 100;
    if (margin > highestMargin)
    {
        highestMargin = margin;
        highestIndustry = name;
    }
    if (margin < lowestMargin)
    {
        lowestMargin = margin;
        lowestIndustry = name;
    }
