#include <iostream>
#include <string>
#include <regex>
using namespace std;
int main() {
  string age, gender, location;
  regex age_regex("[0-9]{1,3}");
  regex location_regex("[A-Za-z0-9]+");
  // Get age input and validate
  cout << "Enter your age: ";
  cin >> age;
  while (!regex_match(age, age_regex)) {
    cout << "Invalid input. Please enter a valid age: ";
    cin >> age;
  }
  // Get gender input and validate
  cout << "Enter your gender (male/female/other): ";
  cin >> gender;
  while (gender != "male" && gender != "female" && gender != "other") {
    cout << "Invalid input. Please enter a valid gender: ";
    cin >> gender;
  }
  // Get location input and validate
  cout << "Enter your location: ";
  cin >> location;
  while (!regex_match(location, location_regex)) {
    cout << "Invalid input. Please enter a valid location: ";
    cin >> location;
  }
