def complex_sort(llist):
    def compare_complex(a, b):
        if a.real < b.real:
            return -1
        elif a.real > b.real:
            return 1
        else:
            if a.imag < b.imag:
                return -1
            elif a.imag > b.imag:
                return 1
            else:
                return 0
    return sorted(llist, key=compare_complex)
```

