            words[i] = antonyms[words[i]];
        }
    }
    sentence = "";
    for (int i = 0; i < words.size(); i++) {
        sentence += words[i];
        if (i != words.size() - 1) {
            sentence += " ";
        }
    }
}
// function to transform sentence to negative statement
string transform_to_negative(string sentence, unordered_map<string, string>& antonyms, vector<string>& prohibited) {
    // replace prohibited words with their antonyms
    replace_prohibited_words(sentence, antonyms);
    // transform sentence to negative statement
    string negation = "isn't";
    for (int i = 0; i < prohibited.size(); i++) {
        if (sentence.find(prohibited[i]) != string::npos) {
            negation = "is";
            break;
        }
    }
    sentence[0] = toupper(sentence[0]);
    return sentence + " " + negation;
}
