    Map<String, Integer> horse = new HashMap<>();
    adjList.put("horse", horse);
    int shortestPathBC = shortestPath(adjList, "buffalo", "cattle");
    int shortestPathBH = shortestPath(adjList, "buffalo", "horse");
    int shortestPathCH = shortestPath(adjList, "cattle", "horse");
    System.out.println("Shortest path between buffalo and cattle: " + shortestPathBC);
    System.out.println("Shortest path between buffalo and horse: " + shortestPathBH);
    System.out.println("Shortest path between cattle and horse: " + shortestPathCH);
}
```
