library(WordNet)
# Function to replace verbs and adjectives with antonyms
replace_with_antonyms <- function(sentence){
  words <- strsplit(sentence, " ")[[1]]
  tags <- pos_tag(words)
  for (i in seq_along(words)){
    if (tags[i] == "VB" | tags[i] == "VBD" | tags[i] == "VBG" | tags[i] == "VBN" | tags[i] == "VBP" | tags[i] == "VBZ"){
      antonyms <- antonyms(words[i], pos = "verb")
      if (length(antonyms) > 0){
        words[i] <- antonyms[[1]]
      }
    } else if (tags[i] == "JJ" | tags[i] == "JJR" | tags[i] == "JJS"){
      antonyms <- antonyms(words[i], pos = "adj")
      if (length(antonyms) > 0){
        words[i] <- antonyms[[1]]
      }
    }
  }
  return(paste(words, collapse = " "))
}
